INT = {'133':('6411179','Punto 9'),'134':('a88c724','Project-First A1'),'135':('ba60b94','Project-First A2'),'136':('bf147e1','Project-First A3'),
 '137':('2edfb98','Project-First A4'),'138':('f585468','Fase B B1'),'139':('5f89957','Fase B B2'),'140':('96b44ee','Fase B B3'),'141':('77fa761','Fase B B4'),
 '142':('06abd54','Fase B B5'),'143':('9cc460b','Fase B B6'),'145':('3495c46','Fase B B7'),'146':('c86d496','Fase B B8'),'147':('902bc44','Fase C C1'),
 '148':('c317d9e','Fase C C2'),'149':('de75f30','Fase C C3'),'150':('b44d40d+9a21b25','FT3D-1a'),'151':('579189d','FT3D-1b')}
